void AKTWRogueRun::BuildArena(){FloorMaterial=NewObject<UPhysicalMaterial>(this);FloorMaterial->Friction=.6f;FloorMaterial->Restitution=.05f;FloorMaterial->bOverrideFrictionCombineMode=true;FloorMaterial->FrictionCombineMode=EFrictionCombineMode::Min;
 auto Part=[&](const TCHAR* Name,FVector P,FVector Size,const TCHAR* Material,bool Collision){auto* C=NewObject<UStaticMeshComponent>(this,MakeUniqueObjectName(this,UStaticMeshComponent::StaticClass(),Name));AddInstanceComponent(C);C->SetupAttachment(RootComponent);C->SetStaticMesh(LoadObject<UStaticMesh>(nullptr,TEXT("/Engine/BasicShapes/Cube.Cube")));C->SetRelativeLocation(P);C->SetRelativeScale3D(Size/100);C->SetMaterial(0,LoadObject<UMaterialInterface>(nullptr,Material));C->SetCollisionEnabled(Collision?ECollisionEnabled::QueryAndPhysics:ECollisionEnabled::NoCollision);if(Collision){C->SetCollisionProfileName(TEXT("BlockAll"));C->SetPhysMaterialOverride(FloorMaterial);}C->RegisterComponent();return C;};
 Part(TEXT("ArenaRoad"),FVector(0,0,-100),FVector(3600,1800,200),TEXT("/Game/KTW/Materials/M_MainRoad.M_MainRoad"),true);
 for(int I=-17;I<=17;++I){Part(TEXT("RimStripe"),FVector(I*100,880,3),FVector(55,28,4),TEXT("/Game/KTW/Materials/M_NeonGold.M_NeonGold"),false);Part(TEXT("RimStripe"),FVector(I*100,-880,3),FVector(55,28,4),TEXT("/Game/KTW/Materials/M_NeonGold.M_NeonGold"),false);}
 for(float X:{-200.f,200.f})for(int I=-7;I<=7;++I)Part(TEXT("DeployLine"),FVector(X,I*100,3),FVector(12,55,4),X<0?TEXT("/Game/KTW/Materials/M_Blue.M_Blue"):TEXT("/Game/KTW/Materials/M_Red.M_Red"),false);
 for(int I=-6;I<=6;++I)Part(TEXT("LaneMark"),FVector(I*240,0,3),FVector(110,10,3),TEXT("/Game/KTW/Materials/M_SnowWhite.M_SnowWhite"),false);
 for(int I=0;I<4;++I){auto* C=Part(TEXT("RogueDanger"),FVector(0,0,6),FVector(1,1,4),TEXT("/Game/KTW/Materials/M_Red.M_Red"),false);C->ComponentTags={TEXT("RogueDanger"),FName(*FString::FromInt(I))};C->SetHiddenInGame(true);}
 if(auto* Art=FKTWImportedArt::Data())for(int I=0;I<12;++I){auto* Mesh=Art->Meshes.Find(100+I%8);if(!Mesh||!Mesh->Get())continue;auto* C=NewObject<UStaticMeshComponent>(this);AddInstanceComponent(C);C->SetupAttachment(RootComponent);C->SetStaticMesh(Mesh->Get());const FVector P((I%6-2.5f)*950,I<6?2300:-2300,-1600);const FTransform T(FRotator(0,I<6?180:0,0),P,FVector(7,5,20+I%3*5));C->SetRelativeTransform(FKTWImportedArt::Fit(T,Mesh->Get()));C->SetCollisionEnabled(ECollisionEnabled::NoCollision);C->RegisterComponent();}
}
AKTWRogueUnit* AKTWRogueRun::Spawn(int32 TypeIndex,int32 TeamIndex,FVector P,int32 Slot){if(!SoldierTypes.IsValidIndex(TypeIndex))return nullptr;P.Z=88*SoldierTypes[TypeIndex].Scale+4;auto* U=GetWorld()->SpawnActorDeferred<AKTWRogueUnit>(AKTWRogueUnit::StaticClass(),FTransform(FRotator(0,TeamIndex?180:0,0),P),nullptr,nullptr,ESpawnActorCollisionHandlingMethod::AlwaysSpawn);U->Run=this;U->Type=TypeIndex;U->Team=TeamIndex;U->RosterSlot=Slot;U->FinishSpawning(FTransform(FRotator(0,TeamIndex?180:0,0),P));Units.Add(U);return U;}
void AKTWRogueRun::Prepare(){for(auto U:Units)if(IsValid(U))U->Destroy();Units.Empty();for(auto P:Projectiles)if(IsValid(P))P->Deactivate();Selected.Empty();Selecting=false;Phase=EKTWRoguePhase::Deployment;Elapsed=0;{TInlineComponentArray<UStaticMeshComponent*> Parts;GetComponents(Parts);for(auto* C:Parts)if(C->ComponentHasTag(TEXT("RogueDanger")))C->SetHiddenInGame(true);}RebuildRules();while(Positions.Num()<Roster.Num()){const int I=Positions.Num();Positions.Add(DeploymentPoint(I));}for(int I=0;I<Roster.Num();++I)Spawn(Roster[I],0,Positions[I],I);const auto EnemyPoints=EnemyFormation(Wave);for(int I=0;I<Waves[Wave].Soldiers.Num();++I)Spawn(Waves[Wave].Soldiers[I],1,EnemyPoints[I]);Notice=TEXT("左键选中己方单位，再点蓝方地面调整位置；Shift追加。空格开战。");}
bool AKTWRogueRun::Place(AKTWRogueUnit* Unit,FVector Point){return PlaceSquad({Unit},{Point});}
void AKTWRogueRun::AutoDeploy(){if(Phase!=EKTWRoguePhase::Deployment)return;for(auto U:Units)if(U&&U->Team==0){const int I=U->RosterSlot;Positions[I]=DeploymentPoint(I);U->SetActorLocation(Positions[I]+FVector(0,0,88*U->Stats.Scale+4));}}
bool AKTWRogueRun::Buy(int32 TypeIndex){if((Phase!=EKTWRoguePhase::Deployment&&Phase!=EKTWRoguePhase::Shop)||!SoldierTypes.IsValidIndex(TypeIndex)||Roster.Num()>=MaxRoster||Coins<SoldierTypes[TypeIndex].Cost)return false;FVector FreePoint;bool Free=false;for(int Candidate=0;Candidate<MaxRoster;++Candidate){const FVector P=DeploymentPoint(Candidate);bool Occupied=false;for(const FVector& Existing:Positions)if(FVector::Dist2D(P,Existing)<120){Occupied=true;break;}if(!Occupied){FreePoint=P;Free=true;break;}}if(!Free){Notice=TEXT("Make room in your formation before recruiting.");return false;}if(auto* Profile=UKTWSession::Get(this)){Profile->Earn(TEXT("recruit"));if(TypeIndex==5)Profile->Earn(TEXT("gunner"));}Coins-=SoldierTypes[TypeIndex].Cost;Roster.Add(TypeIndex);const int I=Roster.Num()-1;Positions.Add(FreePoint);if(Phase==EKTWRoguePhase::Deployment)Spawn(TypeIndex,0,Positions.Last(),I);Notice=TEXT("Recruited permanently for this run. Fallen units return next wave.");return true;}
void AKTWRogueRun::StartBattle(){if(Phase!=EKTWRoguePhase::Deployment||!ConfigOK)return;for(auto U:Units)if(U&&U->Team==0){const FVector P=U->GetActorLocation();if(P.X>-200||P.X<-1700||FMath::Abs(P.Y)>800){Notice=TEXT("All allied units must be inside the blue deployment zone.");return;}}Phase=EKTWRoguePhase::Battle;Elapsed=0;for(auto U:Units)if(U)U->Activate(true);Notice=TEXT("左键或右键选兵，右键地面移动，右键敌人集火。中键旋转镜头。");}
int32 AKTWRogueRun::Living(int32 TeamIndex)const{int N=0;for(auto U:Units)if(IsValid(U)&&U->Alive&&U->Team==TeamIndex)++N;return N;}
void AKTWRogueRun::Complete(bool Victory){if(Phase!=EKTWRoguePhase::Battle)return;Selecting=false;Won=Victory;Speed=1;UGameplayStatics::SetGlobalTimeDilation(GetWorld(),1);for(auto U:Units)if(IsValid(U)){U->Body->SetPhysicsLinearVelocity(FVector::ZeroVector);U->Body->SetPhysicsAngularVelocityInRadians(FVector::ZeroVector);U->Body->SetSimulatePhysics(false);}for(auto P:Projectiles)if(P)P->Deactivate();if(Victory){if(auto* Profile=UKTWSession::Get(this)){Profile->Earn(TEXT("first_wave"));if(Wave==Waves.Num()-1)Profile->Earn(TEXT("champion"));}Coins+=BaseReward+WaveReward*Wave+SurvivorReward*Living(0);Phase=Wave==Waves.Num()-1?EKTWRoguePhase::Victory:EKTWRoguePhase::Result;Notice=Wave==Waves.Num()-1?TEXT("All five waves cleared. Your gang owns the rooftop."):TEXT("Victory. Choose a rule, recruit and prepare for the next wave.");}else{Lives=FMath::Max(0,Lives-1);Phase=Lives>0?EKTWRoguePhase::Result:EKTWRoguePhase::GameOver;Notice=Lives>0?TEXT("One legion life lost. Your roster and rules are kept for a retry."):TEXT("Legion lives exhausted. Start a fresh rule run.");}}
void AKTWRogueRun::Tick(float D){Super::Tick(D);
#if !UE_BUILD_SHIPPING
 if(FParse::Param(FCommandLine::Get(),TEXT("KTWRogueSoak"))){if(Phase==EKTWRoguePhase::Deployment){for(int I=0;I<20;++I){const int Type=(I%4==0?5:I%4==1?2:I%4==2?3:0);if(!Buy(Type)&&!Buy(0))break;}StartBattle();}else if(Phase==EKTWRoguePhase::Result){if(Won)DraftRules();else Retry();}else if(Phase==EKTWRoguePhase::Draft){int Best=Choices[0];for(int I:Choices)if(I==6||I==1||I==5)Best=I;Action(FString::Printf(TEXT("Card%d"),Best));}else if(Phase==EKTWRoguePhase::Shop){for(int I=0;I<20;++I)if(!Buy(Shop[I%4]))break;NextWave();}else if(Phase==EKTWRoguePhase::Victory||Phase==EKTWRoguePhase::GameOver){bool OK=ConfigOK&&Coins>=0&&Lives>=0&&Projectiles.Num()<=ProjectileLimit&&WorstLiveTilt<2&&WalkingSamples>0&&AttackSamples>0&&GunnerShots>0;for(auto U:Units)if(U)OK&=!U->GetActorLocation().ContainsNaN();UE_LOG(LogTemp,Display,TEXT("KTW ROGUE SOAK COMPLETE failures=%d wave=%d won=%d lives=%d tilt=%.3f walks=%d attacks=%d gunshots=%d"),OK?0:1,Wave+1,Phase==EKTWRoguePhase::Victory,Lives,WorstLiveTilt,WalkingSamples,AttackSamples,GunnerShots);FPlatformMisc::RequestExitWithStatus(false,OK?0:1);return;}}
#endif
 if(Phase!=EKTWRoguePhase::Battle)return;Elapsed+=D;if(Elapsed>CollapseAt){const float Shrink=FMath::FloorToFloat((Elapsed-CollapseAt)/3)*150,HX=FMath::Max(100.f,1800-Shrink),HY=FMath::Max(100.f,900-Shrink);TInlineComponentArray<UStaticMeshComponent*> Parts;GetComponents(Parts);for(auto* C:Parts)if(C->ComponentHasTag(TEXT("RogueDanger"))){const int I=FCString::Atoi(*C->ComponentTags[1].ToString());C->SetHiddenInGame(false);C->SetRelativeLocation(I<2?FVector((I?1:-1)*(1800+HX)*.5f,0,6):FVector(0,(I==3?1:-1)*(900+HY)*.5f,6));C->SetRelativeScale3D(I<2?FVector(FMath::Max(1.f,1800-HX)/100,18,.04):FVector(36,FMath::Max(1.f,900-HY)/100,.04));}}
 for(auto U:Units)if(IsValid(U)&&U->Alive&&Elapsed>CollapseAt){const float Shrink=FMath::FloorToFloat((Elapsed-CollapseAt)/3)*150;const FVector P=U->GetActorLocation();if(FMath::Abs(P.X)>FMath::Max(100.f,1800-Shrink)||FMath::Abs(P.Y)>FMath::Max(100.f,900-Shrink)){U->Receive(nullptr,U->MaxHealth*.15f*D,FVector::ZeroVector);U->Body->AddForce(-P.GetSafeNormal2D()*U->Body->GetMass()*300);}}
 // Resolve after the physics/death events, so simultaneous annihilation favours the player.
 if(Living(1)==0){Complete(true);return;}if(Living(0)==0){Complete(false);return;}if(Elapsed>=Deadline){float Strength[2]={0,0};for(auto U:Units)if(U&&U->Alive)Strength[U->Team]+=U->Health/U->MaxHealth;Complete(Strength[0]>=Strength[1]);}}
void AKTWRogueRun::RebuildRules(){Rules=FKTWRogueRules();for(int Index:ActiveCards)if(CardTypes.IsValidIndex(Index)){const auto& C=CardTypes[Index];Rules.Gravity*=C.Gravity;Rules.Knockback*=C.Knockback;Rules.Friction=FMath::Min(Rules.Friction,C.Friction);Rules.EnemyMass*=C.EnemyMass;Rules.DeathRadius=FMath::Max(Rules.DeathRadius,C.DeathRadius);Rules.DeathDamage+=C.DeathDamage;Rules.DeathImpulse+=C.DeathImpulse;Rules.GrowthScale*=C.GrowthScale;Rules.GrowthMass*=C.GrowthMass;Rules.GrowthDamage*=C.GrowthDamage;Rules.GrowthStacks=FMath::Max(Rules.GrowthStacks,C.GrowthStacks);Rules.Bounces=FMath::Max(Rules.Bounces,C.Bounces);Rules.BounceDamage*=C.BounceDamage;Rules.FriendlySafe|=C.FriendlySafe;}Rules.Gravity=FMath::Clamp(Rules.Gravity,.15f,3.f);Rules.Knockback=FMath::Clamp(Rules.Knockback,.1f,8.f);Rules.EnemyMass=FMath::Clamp(Rules.EnemyMass,.2f,3.f);if(FloorMaterial){FloorMaterial=NewObject<UPhysicalMaterial>(this);FloorMaterial->Friction=Rules.Friction;FloorMaterial->Restitution=.05f;FloorMaterial->bOverrideFrictionCombineMode=true;FloorMaterial->FrictionCombineMode=EFrictionCombineMode::Min;TInlineComponentArray<UStaticMeshComponent*> Parts;GetComponents(Parts);for(auto* C:Parts)if(C->GetCollisionEnabled()!=ECollisionEnabled::NoCollision)C->SetPhysMaterialOverride(FloorMaterial);}}
void AKTWRogueRun::DraftRules(){Choices.Empty();TArray<int32> Pool;for(int I=0;I<CardTypes.Num();++I)if(!ActiveCards.Contains(I))Pool.Add(I);while(Choices.Num()<3&&!Pool.IsEmpty()){const int P=Random.RandRange(0,Pool.Num()-1);Choices.Add(Pool[P]);Pool.RemoveAt(P);}Phase=EKTWRoguePhase::Draft;}
void AKTWRogueRun::RefreshShop(bool Paid){if(Phase!=EKTWRoguePhase::Shop)return;if(Paid){if(Coins<RefreshCost)return;Coins-=RefreshCost;}Shop.Empty();Shop.Add(5);for(int I=1;I<4;++I)Shop.Add(Random.RandRange(0,Wave>=1?4:3));}
void AKTWRogueRun::Retry(){if(Phase==EKTWRoguePhase::Result&&!Won&&Lives>0)Prepare();}
void AKTWRogueRun::NextWave(){if(Phase!=EKTWRoguePhase::Shop||Wave>=Waves.Num()-1)return;++Wave;Prepare();}
void AKTWRogueRun::ApplyKill(AKTWRogueUnit* Killer,AKTWRogueUnit*){if(Killer&&Killer->Alive){Killer->Grow();if(Killer->Team==0)if(auto* Profile=UKTWSession::Get(this))Profile->Earn(TEXT("first_kill"));}}
void AKTWRogueRun::ApplyDeath(AKTWRogueUnit* Victim,AKTWRogueUnit*){if(!Victim||Victim->Team!=0||Rules.DeathRadius<=0)return;const FVector P=Victim->GetActorLocation();auto* Flash=GetWorld()->SpawnActor<AActor>();auto* Ring=NewObject<UStaticMeshComponent>(Flash);Flash->SetRootComponent(Ring);Flash->AddInstanceComponent(Ring);Ring->SetStaticMesh(LoadObject<UStaticMesh>(nullptr,TEXT("/Engine/BasicShapes/Cylinder.Cylinder")));Ring->SetMaterial(0,LoadObject<UMaterialInterface>(nullptr,TEXT("/Game/KTW/Materials/M_NeonGold.M_NeonGold")));Ring->SetCollisionEnabled(ECollisionEnabled::NoCollision);Ring->RegisterComponent();Flash->SetActorLocation(FVector(P.X,P.Y,8));Flash->SetActorScale3D(FVector(Rules.DeathRadius/50,Rules.DeathRadius/50,.02));Flash->SetLifeSpan(.22f);TArray<TObjectPtr<AKTWRogueUnit>> Snapshot=Units;for(auto U:Snapshot)if(U&&U->Alive&&U!=Victim){const FVector Diff=U->GetActorLocation()-P;if(Diff.Size()<=Rules.DeathRadius)U->Receive(Victim,Rules.DeathDamage,(Diff.GetSafeNormal2D()+FVector(0,0,.4f)).GetSafeNormal()*Rules.DeathImpulse*Rules.Knockback);}}
void AKTWRogueRun::Fire(AKTWRogueUnit* Unit,AKTWRogueUnit* Enemy){AKTWRogueProjectile* Shot=nullptr;for(auto P:Projectiles)if(P&&!P->Active){Shot=P;break;}if(!Shot&&Projectiles.Num()<ProjectileLimit){Shot=GetWorld()->SpawnActor<AKTWRogueProjectile>();Projectiles.Add(Shot);}if(!Shot&&!Projectiles.IsEmpty()){Shot=Projectiles[0];Projectiles.RemoveAt(0);Projectiles.Add(Shot);Shot->Deactivate();}if(Shot){Projectiles.Remove(Shot);Projectiles.Add(Shot);Shot->Launch(Unit,Enemy);}}
